import sys
from collections import Counter

MOD = 998244353

data = list(map(int, sys.stdin.buffer.read().split()))
n, m = data[0], data[1]

points = []
pos = 2
for _ in range(n):
    x = data[pos]
    y = data[pos + 1]
    pos += 2
    points.append((x, y))

options = Counter()
for mask in range(1 << n):
    px = nx = py = ny = 0
    for j, (x, y) in enumerate(points):
        if (mask >> j) & 1:
            if x > 0:
                px += x
            else:
                nx += abs(x)
            if y > 0:
                py += y
            else:
                ny += abs(y)
    options[(px, nx, py, ny)] += 1

groups = [[[] for _ in range(2)] for _ in range(2)]
for (px, nx, py, ny), count in options.items():
    groups[(px - nx) & 1][(py - ny) & 1].append(
        (px, nx, py, ny, count)
    )

flag_maps = {}
for bit in range(2):
    for cx in range(2):
        for cy in range(2):
            mapping = []
            for old in range(4):
                bx = old >> 1
                by = old & 1
                nbx = bx if cx == bit else int(cx > bit)
                nby = by if cy == bit else int(cy > bit)
                mapping.append((nbx << 1) | nby)
            flag_maps[(bit, cx, cy)] = mapping

dp = {(0, 0, 0, 0): [1, 0, 0, 0]}

for i in range(30):
    bit = (m >> i) & 1
    ndp = {}

    for (cpx, cnx, cpy, cny), values in dp.items():
        gx = (cpx - cnx) & 1
        gy = (cpy - cny) & 1

        for px, nx, py, ny, count in groups[gx][gy]:
            npx = cpx + px
            nnx = cnx + nx
            npy = cpy + py
            nny = cny + ny

            a = npx >> 1
            b = nnx >> 1
            c = npy >> 1
            d = nny >> 1

            if a > 19 or b > 19 or c > 19 or d > 19:
                continue

            key = (a, b, c, d)
            target = ndp.get(key)
            if target is None:
                target = [0, 0, 0, 0]
                ndp[key] = target

            mapping = flag_maps[(bit, npx & 1, npy & 1)]
            for old_flag, value in enumerate(values):
                if value:
                    new_flag = mapping[old_flag]
                    target[new_flag] = (
                        target[new_flag] + value * count
                    ) % MOD

    dp = ndp

answer = dp.get((0, 0, 0, 0), [0, 0, 0, 0])[0]
print((answer - 1) % MOD)

import sys

MOD = 998244353

data = list(map(int, sys.stdin.buffer.read().split()))
it = iter(data)
n = next(it)
m = next(it)

x = [0] * n
y = [0] * n
for i in range(n):
    x[i] = next(it)
    y[i] = next(it)

size = 1 << n
px = [0] * size
nx = [0] * size
py = [0] * size
ny = [0] * size

for mask in range(size):
    for j in range(n):
        if (mask >> j) & 1:
            if x[j] > 0:
                px[mask] += abs(x[j])
            else:
                nx[mask] += abs(x[j])
            if y[j] > 0:
                py[mask] += abs(y[j])
            else:
                ny[mask] += abs(y[j])

delta_counts = {}
for mask in range(size):
    delta = (px[mask], nx[mask], py[mask], ny[mask])
    delta_counts[delta] = delta_counts.get(delta, 0) + 1
deltas = [(a, b, c, d, count)
          for (a, b, c, d), count in delta_counts.items()]

flag_maps = [[None] * 4 for _ in range(2)]
for bit in range(2):
    for cx in range(2):
        for cy in range(2):
            mapping = [0] * 4
            for old in range(4):
                bx = old >> 1
                by = old & 1
                nbx = bx if cx == bit else int(cx > bit)
                nby = by if cy == bit else int(cy > bit)
                mapping[old] = (nbx << 1) | nby
            flag_maps[bit][(cx << 1) | cy] = mapping

dp = {(0, 0, 0, 0): [1, 0, 0, 0]}

for i in range(30):
    bit = (m >> i) & 1
    ndp = {}

    for (cpx, cnx, cpy, cny), values in dp.items():
        for dpx, dnx, dpy, dny, count in deltas:
            npx = cpx + dpx
            nnx = cnx + dnx
            npy = cpy + dpy
            nny = cny + dny

            if (npx & 1) != (nnx & 1):
                continue
            if (npy & 1) != (nny & 1):
                continue

            cx = npx & 1
            cy = npy & 1
            key = (npx >> 1, nnx >> 1, npy >> 1, nny >> 1)

            if key[0] > 19 or key[1] > 19 or key[2] > 19 or key[3] > 19:
                continue

            target = ndp.get(key)
            if target is None:
                target = [0, 0, 0, 0]
                ndp[key] = target

            mapping = flag_maps[bit][(cx << 1) | cy]
            for old_flag, value in enumerate(values):
                if value:
                    increment = value if count == 1 else value * count % MOD
                    new_flag = mapping[old_flag]
                    total = target[new_flag] + increment
                    if total >= MOD:
                        total -= MOD
                    target[new_flag] = total

    dp = ndp

answer = dp.get((0, 0, 0, 0), [0, 0, 0, 0])[0]
print((answer - 1) % MOD)

